# regenerate test and apply inferred rule: bbox frame + fill interior rows/cols with >=3 foreground cells strictly inside bbox
base=[[6]*29 for _ in range(8)]
for c in list(range(1,13))+list(range(14,20))+list(range(23,28)): base[2][c]=9
for r in [3,4,6]: base[r][1]=base[r][27]=9
for c in list(range(1,7))+list(range(8,11))+[12,14]+list(range(16,21))+[22,23,26,27]: base[5][c]=9
for c in [1]+list(range(3,12))+[15,16]+list(range(18,23))+list(range(24,28)): base[7][c]=9
out=[row[:] for row in base]
# frame
for c in range(1,28):
    for r in (2,7):
        if out[r][c]==6: out[r][c]=2
for r in range(2,8):
    for c in (1,27):
        if out[r][c]==6: out[r][c]=2
# internal rows with >=3 markers strictly inside bbox; fill between first/last marker
for r in range(3,7):
    cs=[c for c in range(2,27) if base[r][c]==9]
    if len(cs)>=3:
        for c in range(min(cs),max(cs)+1):
            if out[r][c]==6: out[r][c]=2
# internal cols with >=3 marks strictly inside bbox
for c in range(2,27):
    rs=[r for r in range(3,7) if base[r][c]==9]
    if len(rs)>=3:
        for r in range(min(rs),max(rs)+1):
            if out[r][c]==6: out[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out))
